gNh(){return"\u0625\u0643\u0645\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f"},
gNm(){return"\u0625\u0632\u0627\u0644\u0629 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u063a\u064a\u0631 \u0627\u0644\u0645\u0643\u062a\u0645\u0644"},
gNp(){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0639\u0627\u0645\u0644"},
