gLX(){return"\u0645\u0642\u0631\u0648\u0621"},
gyR(){return"\u062a\u0645\u0651 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0643\u0645\u0642\u0631\u0648\u0621"},
