gBy(){return"\u0646\u0642\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u062a\u0643\u0641\u064a \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u062f\u0648\u0646 \u0643\u062a\u0627\u0628\u0629 \u0623\u064a \u0634\u064a\u0621. \u0644\u0630\u0644\u0643 \u064a\u0645\u0643\u0646 \u0644\u0623\u064a \u0634\u062e\u0635 \u064a\u0633\u062a\u0637\u064a\u0639 \u0641\u062a\u062d \u0642\u0641\u0644 \u0647\u0630\u0627 \u0627\u0644\u0647\u0627\u062a\u0641 \u0623\u0646 \u064a\u0641\u062a\u062d \u0647\u0630\u0647 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0642\u0636\u0627\u0626\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u064a\u062d\u0647\u0627."},
Bs(a){return"\u0622\u062e\u0631 \u0627\u062a\u0635\u0627\u0644: "+a},
grQ(){return"\u0646\u0633\u064a\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628"},
Bq(a){return"\u0646\u0633\u064a\u0627\u0646 "+a+"\u061f \u0633\u062a\u064f\u0645\u062d\u0649 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0645\u0646 \u0627\u0644\u062e\u0632\u0646\u0629 \u0627\u0644\u0645\u0634\u0641\u0651\u0631\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u0648\u0633\u064a\u0644\u0632\u0645 \u0625\u062f\u062e\u0627\u0644\u0647\u0627 \u0645\u0646 \u062c\u062f\u064a\u062f \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644."},
gBr(){return"\u062a\u0645 \u0646\u0633\u064a\u0627\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632"},
